  row: HTMLElement,
  key: {metaKey: boolean; ctrlKey: boolean; shiftKey: boolean; altKey: boolean},
): void {
  row.dispatchEvent(
    new MouseEvent('click', {
      bubbles: true,
      cancelable: true,
      composed: true,
      metaKey: key.metaKey,
      ctrlKey: key.ctrlKey,
      shiftKey: key.shiftKey,
      altKey: key.altKey,
    }),
  );
