function endPress() {
  pressPointerId = null;
  unsubscribePress?.();
  unsubscribePress = null;
}

function markContextMenu() {
  contextMenuGesture = gesture;
}

function markClicked() {
  clickedGesture = gesture;
}

function listen() {
