export function slideRulesCss(): string {
  return [
    ...PLACEMENTS.flatMap(placement =>
      ALIGNMENTS.flatMap(alignment => [
        rule(placement, alignment, 'same'),
        rule(placement, alignment, 'opposite'),
      ]),
    ),
    besideRule('end'),
    besideRule('start'),
    fitRule('above'),
    fitRule('below'),
  ].join('');
