  const px = (name: string) => parseFloat(style.getPropertyValue(name)) || 0;
  const isContentBox = style.getPropertyValue('box-sizing') !== 'border-box';
  const extra = (sides: [string, string]) =>
    isContentBox
      ? sides.reduce(
          (sum, side) =>
            sum + px(`padding-${side}`) + px(`border-${side}-width`),
          0,
        )
      : 0;
