  }
  if (saved.timing != null) {
    const timing = next.getTiming() as unknown as Writable;
    const changed: Writable = {};
    for (const [field, value] of Object.entries(saved.timing)) {
      if (differs(value, timing[field])) {
        changed[field] = value;
      }
