export function carryAnimations(
  saved: SavedAnimations,
  copy: Element,
  copyOf: (element: Element) => Element | null,
): void {
  if (typeof copy.getAnimations !== 'function') {
    return;
  }
  restoreAnimations(
    copy,
    saved.flatMap(state => retarget(state, copyOf) ?? []),
