  if (event.kind === 'buttonDown') {
    // Nothing can turn a mouse button or a key into a scroll, so there is
    // nothing to wait for: paint now, as `:active` does on a desktop.
    return {
      gesture: {originX: 0, originY: 0, phase: 'buttonHeld'},
      paint: 'on',
      timer: null,
