    case 'armed':
      if (event.kind === 'move') {
        // Travel is a scroll. Nothing was painted, so nothing is removed; the
        // gesture is simply over.
        return travelled(gesture, event.x, event.y)
          ? step(gesture, 'dead', 'none', null)
          : {gesture, paint: 'none', timer: null};
