    const found = new Set<ShadowRoot>();
    for (const range of ranges) {
      for (const [node, offset] of [
        [range.startContainer, range.startOffset],
        [range.endContainer, range.endOffset],
      ] as const) {
        for (const child of [
          node.childNodes[offset],
          node.childNodes[offset - 1],
